-- ---------------------------------------------------------------------------------------------
-- DMT (dmtgt) - PRE-DEPLOYMENT SCRIPT FOR THE MNAO MARKET (en-US, es-MX, fr-CA, en-CA)
--   The MNAO source content moves to the MC / MME folder layout
--       <locale>\<model>\<manual>\<FLxxxx>\<material>
--   so every MNAO row already in the DMT tables is given the facelift folder FL0000.
--
--   1. New column dc_facelift_folder_name on gms3_dmt_<locale>_imdoc (4 locales)
--   2. New tables gms3_dmt_<locale>_dispord (display order) and gms3_dmt_<locale>_esicat
--      (esicat.txt rows) - 4 locales each. NO CD table: MNAO has no CD processing.
--   3. New column vc_content_status on the MNAO view content tables gms3_vc_vin_details and
--      gms3_vc_model_year_details (same steps as dmtgt_pre_deployment.sql / dmtgt_mme_pre_deployment.sql)
--   4. Display order columns (disp_code/name 1-6 + dispord_seq_no) on both view content tables
--   5. Functional index on the source path of gms3_dmt_en_ca_imdoc (the other 3 locales have it)
--   6. dc_facelift_folder_name = 'FL0000' on every existing imdoc row
--   7. ONE-TIME PATH REWRITE: 'FL0000\' inserted after the 3rd backslash of every MNAO source path
--         en-US\CX-5_KF\WM\<material>\ent.gms3\x.ent  ->  en-US\CX-5_KF\WM\FL0000\<material>\ent.gms3\x.ent
--      in gms3_dmt_<locale>_{imdoc,cat,vin,vinattr,vinmaster,cvc,inrlks} (inrlks: also the link target
--      column dc_inner_doc_link_path), gms3_vc_vin_details.vc_vin_source_ntwrk_loc (MNAO locales only)
--      and gms3_vc_model_year_details.vc_my_source_ntwrk_loc (MNAO locales only).
--      NOT touched: gms3_dmt_conv_* , gms3_dmt_conv_reprpse_doc(_tmp), gms3_dmt_imdoc_child_map(_t)
--      (no longer used by DMT).
--   8. Checks
-- ---------------------------------------------------------------------------------------------
-- RUN THIS SCRIPT ON kapture_dc BEFORE THE dmtgt.war WITH THE MNAO CHANGES IS DEPLOYED.
-- dmtgt_pre_deployment.sql, dmtgt_preview_docs.sql and dmtgt_publish.sql must have been run already.
--
-- Plain SQL statements only (no procedures, no DELIMITER, no PREPARE), so it runs in any client:
-- SQL Developer (Run Script / F5), Workbench (Execute All) or the mysql client.
-- Every table is written with its schema (kapture_dc.) - change it there if the schema of the
-- target environment has another name.
--
-- RUNNING IT AGAIN is safe:
--   - ADD COLUMN / CREATE INDEX then fail with "Duplicate column name" / "Duplicate key name" -
--     harmless, the other statements still run. CREATE TABLE uses IF NOT EXISTS.
--   - The path rewrite only changes a path whose 4th segment is not already a facelift folder
--     (FL + 4 digits) and that has at least 4 backslashes, so a path is never changed twice, and
--     link targets without a folder (index?page=result..., #anchor) are never changed.
--
-- SIZE: the path rewrite is split into ranges of 25000 primary key values with a COMMIT after each
-- statement, so no single transaction is large (Group Replication transaction size limit) - the
-- view content table gms3_vc_vin_details alone has ~2.3 million MNAO rows with a path. The ranges
-- are generated up to the highest id of the 2026-09-08 copy of MC Dev; the LAST statement of every
-- table takes all ids above that, so rows written later are covered too. Section 8 counts the paths
-- still without the facelift folder - all counts must be 0.
-- ---------------------------------------------------------------------------------------------

-- ---------------------------------------------------------------------------------------------
-- 0. Before: highest ids (the ranges below go up to the 2026-09-08 values; ids above are covered
--    by the last, open-ended statement of each table)
-- ---------------------------------------------------------------------------------------------
SELECT 'gms3_dmt_en_us_imdoc' AS table_name, COUNT(*) AS row_count, MAX(dc_dd_id) AS max_id FROM kapture_dc.gms3_dmt_en_us_imdoc
UNION ALL
SELECT 'gms3_dmt_en_us_cat' AS table_name, COUNT(*) AS row_count, MAX(dc_cd_id) AS max_id FROM kapture_dc.gms3_dmt_en_us_cat
UNION ALL
SELECT 'gms3_dmt_en_us_vin' AS table_name, COUNT(*) AS row_count, MAX(dc_vin_id) AS max_id FROM kapture_dc.gms3_dmt_en_us_vin
UNION ALL
SELECT 'gms3_dmt_en_us_vinattr' AS table_name, COUNT(*) AS row_count, MAX(dc_vin_attr_id) AS max_id FROM kapture_dc.gms3_dmt_en_us_vinattr
UNION ALL
SELECT 'gms3_dmt_en_us_vinmaster' AS table_name, COUNT(*) AS row_count, MAX(dc_vm_id) AS max_id FROM kapture_dc.gms3_dmt_en_us_vinmaster
UNION ALL
SELECT 'gms3_dmt_en_us_cvc' AS table_name, COUNT(*) AS row_count, MAX(dc_cvc_id) AS max_id FROM kapture_dc.gms3_dmt_en_us_cvc
UNION ALL
