-- ---------------------------------------------------------------------------------------------
-- 7. ONE-TIME PATH REWRITE - 'FL0000\' after the 3rd backslash
-- ---------------------------------------------------------------------------------------------
-- 7. kapture_dc.gms3_dmt_en_us_imdoc (dc_source_network_loc)
UPDATE kapture_dc.gms3_dmt_en_us_imdoc SET dc_source_network_loc = CONCAT(SUBSTRING_INDEX(dc_source_network_loc, CHAR(92), 3), CHAR(92), 'FL0000', CHAR(92), SUBSTRING(dc_source_network_loc, CHAR_LENGTH(SUBSTRING_INDEX(dc_source_network_loc, CHAR(92), 3)) + 2)) WHERE dc_dd_id >= 0 AND dc_dd_id < 25000 AND ((LENGTH(dc_source_network_loc) - LENGTH(REPLACE(dc_source_network_loc, CHAR(92), ''))) >= 4 AND SUBSTRING_INDEX(SUBSTRING_INDEX(dc_source_network_loc, CHAR(92), 4), CHAR(92), -1) NOT REGEXP '^FL[0-9]{4}$');
COMMIT;
UPDATE kapture_dc.gms3_dmt_en_us_imdoc SET dc_source_network_loc = CONCAT(SUBSTRING_INDEX(dc_source_network_loc, CHAR(92), 3), CHAR(92), 'FL0000', CHAR(92), SUBSTRING(dc_source_network_loc, CHAR_LENGTH(SUBSTRING_INDEX(dc_source_network_loc, CHAR(92), 3)) + 2)) WHERE dc_dd_id >= 25000 AND ((LENGTH(dc_source_network_loc) - LENGTH(REPLACE(dc_source_network_loc, CHAR(92), ''))) >= 4 AND SUBSTRING_INDEX(SUBSTRING_INDEX(dc_source_network_loc, CHAR(92), 4), CHAR(92), -1) NOT REGEXP '^FL[0-9]{4}$');
COMMIT;

